def reorder_log_files(logs):
 letters=[];digits=[]
 for log in logs:
  ident,body=log.split(' ',1)
  if body[0].isdigit():digits.append(log)
  else:letters.append((body,ident,log))
 letters.sort()
 return [log for _,_,log in letters]+digits

